 * Cell address parsing and formatting: A1-style addresses with columns A..ZZ
 * and rows 1..999.
 */

const ADDRESS_RE = /^([A-Z]{1,2})([0-9]{1,3})$/

/** Convert 1-2 uppercase letters to a 1-based column number (A=1, Z=26, AA=27, ZZ=702). */
function colLettersToNumber(letters) {
  let n = 0
  for (const ch of letters) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** Convert a 1-based column number back to its 1-2 letter form. */
function colNumberToLetters(num) {
  let s = ''
  let n = num
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parse a raw address token (any case). Returns null when the token is not a
 * valid address (wrong shape, or a row below 1), otherwise
 * { text, col, row } where text is the canonical upper-cased address.
 */
function parseAddress(rawToken) {
  const text = rawToken.toUpperCase()
  const m = ADDRESS_RE.exec(text)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = colLettersToNumber(m[1])
  return { text, col, row }
}

function addressText(col, row) {
  return `${colNumberToLetters(col)}${row}`
}

/** Sort a list of canonical address strings by column then row. */
function sortAddresses(addresses) {
  return [...addresses]
    .map((text) => ({ text, ...parseAddress(text) }))
    .sort((a, b) => (a.col - b.col) || (a.row - b.row))
    .map((a) => a.text)
}

/** Enumerate every address in the rectangle spanned by two corners, in column then row order. */
function rectangleAddresses(a, b) {
  const minCol = Math.min(a.col, b.col)
  const maxCol = Math.max(a.col, b.col)
  const minRow = Math.min(a.row, b.row)
  const maxRow = Math.max(a.row, b.row)
  const result = []
  for (let col = minCol; col <= maxCol; col++) {
    for (let row = minRow; row <= maxRow; row++) {
      result.push(addressText(col, row))
    }
  }
  return result
}

export { parseAddress, addressText, sortAddresses, rectangleAddresses }
"}

