{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-TW57ce/src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 */

class LexError extends Error {}

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = ['^', '*', '/', '+', '-', '=', '<', '>']

function tokenize(body) {
  const tokens = []
  let i = 0
  const n = body.length
  while (i < n) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch === '(') {
      tokens.push({ type: 'LP' })
      i++
      continue
    }
    if (ch === ')') {
      tokens.push({ type: 'RP' })
      i++
      continue
    }
    if (ch === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (ch === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    const two = body.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'OP', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(ch)) {
      tokens.push({ type: 'OP', value: ch })
      i++
      continue
    }
    if (/[0-9]/.test(ch)) {
      let j = i + 1
      while (j < n && /[0-9]/.test(body[j])) j++
      if (body[j] === '.' && /[0-9]/.test(body[j + 1] || '')) {
        j++
        while (j < n && /[0-9]/.test(body[j])) j++
      }
      tokens.push({ type: 'NUM', value: body.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < n && /[A-Za-z0-9]/.test(body[j])) j++
      tokens.push({ type: 'IDENT', value: body.slice(i, j) })
      i = j
      continue
    }
    throw new LexError(`unexpected character ${ch}`)
  }
  return tokens
}

export { tokenize, LexError }
"}

