 * Recursive-descent parser turning a formula's tokens into an AST.
 *
 * Precedence, loosest to tightest: comparisons, then `+`/`-`, then `*`/`/`,
 * then `^` (right-associative), then a leading unary `-`/`+` (which binds
 * tighter than `^`). Ranges (`A1:B3`) are only accepted directly as a whole
 * function argument, never nested inside an expression.
 */

import { tokenize } from './lexer.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const CALL_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class ParseError extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  next() {
    return this.tokens[this.pos++]
  }

  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }

  parseProgram() {
    const node = this.parseComparison()
    if (this.pos !== this.tokens.length) throw new ParseError('trailing tokens')
    return node
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && this.peek().type === 'OP' && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && this.peek().type === 'OP' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.next().value
      const right = this.parsePower()
      left = { type: 'Binary', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek() && this.peek().type === 'OP' && this.peek().value === '^') {
      this.next()
      const right = this.parsePower()
      return { type: 'Binary', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek() && this.peek().type === 'OP' && (this.peek().value === '-' || this.peek().value === '+')) {
      const op = this.next().value
      const node = this.parseUnary()
      return { type: 'Unary', op, node }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.peek()
    if (!token) throw new ParseError('unexpected end of formula')
    if (token.type === 'NUM') {
      this.next()
      return { type: 'Number', value: parseFloat(token.value) }
    }
    if (token.type === 'LP') {
      this.next()
      const node = this.parseComparison()
      this.expect('RP')
      return node
    }
    if (token.type === 'IDENT') {
      this.next()
      const upper = token.value.toUpperCase()
      if (this.peek() && this.peek().type === 'LP') {
        this.next()
        const args = []
        if (!(this.peek() && this.peek().type === 'RP')) {
          args.push(this.parseArgument())
          while (this.peek() && this.peek().type === 'COMMA') {
            this.next()
            args.push(this.parseArgument())
          }
        }
        this.expect('RP')
        return { type: 'Call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'Bool', value: true }
      if (upper === 'FALSE') return { type: 'Bool', value: false }
      return { type: 'Address', text: upper }
    }
    throw new ParseError('unexpected token')
  }

  parseArgument() {
    const token = this.peek()
    const after = this.peek(1)
    if (token && token.type === 'IDENT' && after && after.type === 'COLON') {
      const fromToken = this.next()
      this.next()
      const toToken = this.peek()
      if (!toToken || toToken.type !== 'IDENT') throw new ParseError('expected address after :')
      this.next()
      return { type: 'Range', from: fromToken.value.toUpperCase(), to: toToken.value.toUpperCase() }
    }
    return this.parseComparison()
  }
}

/**
 * Parse a formula body (text after the leading `=`).
 * Returns { ok: true, ast } or { ok: false } when the grammar rejects it.
 */
function parseFormula(body) {
  try {
    const tokens = tokenize(body)
    const parser = new Parser(tokens)
    const ast = parser.parseProgram()
    return { ok: true, ast }
  } catch {
    return { ok: false }
  }
}

export { parseFormula, CALL_NAMES }
"}

