/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { sortAddresses } from './address.js'
import { parseFormula } from './parser.js'
import { collectDeps } from './deps.js'
import { Evaluator } from './evaluator.js'
import { formatValue } from './values.js'

function fail(message, code = 2) {
  process.stderr.write(`${message}\n`)
  process.exit(code)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }
  const mode = argv[0]

  const input = fs.readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(`error: line ${e.line}: ${e.message}`)
    throw e
  }

  const addresses = sortAddresses([...cells.keys()])
  const lines = []

  if (mode === 'values') {
    const evaluator = new Evaluator(cells)
    for (const addr of addresses) {
      lines.push(`${addr}=${formatValue(evaluator.getCellValue(addr))}`)
    }
  } else {
    for (const addr of addresses) {
      const content = cells.get(addr).content
      let deps = []
      if (content.startsWith('=')) {
        const parsed = parseFormula(content.slice(1))
        if (parsed.ok) deps = collectDeps(parsed.ast)
      }
      lines.push(`${addr}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

